'use strict';

const input = $input.first()?.json || {};
const clean = (value, limit = 0) => {
  const normalized = String(value ?? '').normalize('NFKC').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  return limit > 0 ? normalized.slice(0, limit).trim() : normalized;
};
const bool = value => value === true || ['true','1','yes','да'].includes(clean(value).toLowerCase());
const operation = clean(input.operation).toLowerCase();
const principalId = clean(input.principalId || input.principalKey, 200);
const localDate = clean(input.localDate || input.local_date, 10);
const replyToMessageId = clean(input.replyToMessageId, 200);
const replyToText = clean(input.replyToText, 2000);

const identityContext = {
  principalKey: clean(input.principalKey || principalId, 200),
  identitySchemaVersion: clean(input.identitySchemaVersion, 120),
  identityStatus: clean(input.identityStatus, 80),
  tenantId: clean(input.tenantId, 200),
  memoryTenantId: clean(input.memoryTenantId || input.tenantId, 200),
  qdrantCollection: clean(input.qdrantCollection, 240),
  chatId: clean(input.chatId, 120),
  deliveryAddress: clean(input.deliveryAddress || input.chatId, 120),
  userId: clean(input.userId, 160),
  memoryUserId: clean(input.memoryUserId || input.userId, 160),
  telegramUserId: clean(input.telegramUserId || input.userId, 160),
  currentUsername: clean(input.currentUsername || input.username, 160).replace(/^@+/, ''),
  displayName: clean(input.displayName, 240),
  timezone: clean(input.timeZone || input.timezone || 'Asia/Novosibirsk', 120)
};
const messageContext = {
  messageAuthorship: clean(input.messageAuthorship || 'user_authored', 80),
  isForwarded: bool(input.isForwarded),
  replyToMessageId: replyToMessageId || null,
  replyToText: replyToText || null,
  sourceUpdateId: clean(input.sourceUpdateId, 200) || null,
  clarificationKey: clean(input.clarificationKey, 240) || null,
  precedingQuestionKey: clean(input.precedingQuestionKey, 240) || null
};

let stateRpcBody = {};
let stateCoreReady = false;
if (operation === 'intake') {
  const content = clean(input.text || input.messageText || input.question, 12000);
  const sourceMessageId = clean(input.messageId || input.sourceMessageId, 200);
  stateCoreReady = Boolean(
    principalId && clean(input.identitySchemaVersion) && clean(input.memoryTenantId || input.tenantId) &&
    clean(input.qdrantCollection) && sourceMessageId && content && localDate && clean(input.receivedAt)
  );
  stateRpcBody = {
    p_principal_id: principalId,
    p_identity_schema_version: clean(input.identitySchemaVersion, 120),
    p_memory_tenant_id: clean(input.memoryTenantId || input.tenantId, 200),
    p_qdrant_collection: clean(input.qdrantCollection, 240),
    p_source: clean(input.source || 'telegram', 80),
    p_source_message_id: sourceMessageId,
    p_message_kind: clean(input.kind || input.inputType || 'text', 80),
    p_content: content,
    p_received_at: clean(input.receivedAt, 80),
    p_local_date: localDate,
