    p_idempotency_key: clean(input.idempotencyKey, 300) || null
  };
} else if (operation === 'summary') {
  stateCoreReady = Boolean(principalId && localDate);
  stateRpcBody = { p_principal_id: principalId, p_as_of_date: localDate };
