'use strict';

const root = $('Code | Normalize State Core Input | Core').item.json || {};
const incoming = $input.first()?.json || {};
const response = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const values = Array.isArray(response?.state) ? response.state : [];
const expectedSpheres = new Set(['health','energy','mood','calm','clarity','motivation','relationships','progress','inspiration','finance']);
const returnedSpheres = new Set(values.map(value => String(value?.sphereCode || '').trim()));
const validDate = value => {
  const source = String(value || '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(source)) return false;
  const date = new Date(`${source}T00:00:00.000Z`);
  return Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === source;
};
const valid = String(response?.contractVersion || '') === 'chelsea_state_summary_v1' &&
  String(response?.principalId || '') === String(root.principalId || '') &&
  validDate(response?.asOfDate) && String(response.asOfDate) === String(root.localDate || '') &&
  ['calibrating', 'active'].includes(String(response?.mode || '')) &&
  values.length === 10 && returnedSpheres.size === 10 &&
  [...expectedSpheres].every(code => returnedSpheres.has(code)) &&
  values.every(value => Number.isFinite(Number(value?.score)) && Number(value.score) >= 1 && Number(value.score) <= 10 &&
    Number.isFinite(Number(value?.confidence)) && Number(value.confidence) >= 0 && Number(value.confidence) <= 1);
const format = value => {
  const number = Number(value);
  if (!Number.isFinite(number)) return '';
  return Number.isInteger(number) ? String(number) : number.toFixed(2).replace(/0+$/, '').replace(/\.$/, '');
};
const lines = valid ? values
  .slice()
  .sort((a, b) => Number(a.position || 0) - Number(b.position || 0))
  .map(value => {
    const name = String(value.sphereName || value.sphereCode || '').trim();
    const score = format(value.score);
    const confidence = format(value.confidence);
    return name && score ? `- ${name}: ${score}/10${confidence ? ` (уверенность ${confidence})` : ''}` : '';
  })
  .filter(Boolean) : [];
const modeLine = response?.mode === 'calibrating'
  ? `Режим: идёт калибровка до ${String(response.calibrationEndsOn || '').trim()}.`
  : 'Режим: активная оценка.';
const block = valid ? [
  `Предыдущая рассчитанная картина состояния на ${String(response.asOfDate || root.localDate || '').trim()}:`,
  modeLine,
  ...lines,
  'Используй это как дополнительный контекст. Текущее сообщение пользователя имеет приоритет над предыдущей оценкой.'
].join('\n').slice(0, 2600) : '';
return [{ json: {
  ...root,
  stateCoreOk: valid,
  stateCoreOperation: 'summary',
  stateSummaryAvailable: valid,
  stateSummaryBlock: block,
  stateCalibrationStatus: valid ? String(response.mode || '') : '',
  stateSummaryVersion: valid ? 'chelsea_state_summary_block_v1' : '',
  stateSummary: valid ? response : null,
  stateCoreError: valid ? '' : String(response?.message || response?.error || response?.hint || 'state_summary_unavailable').slice(0, 1000)
} }];

